const { RESULTS, RESULT_TYPES, RARITY_LABEL } = require('../../data/results');
const { getTheme, THEMES, buildSharePayload } = require('../../utils/result-engine');
const { getLocalState, hasTestedToday } = require('../../utils/local-state');
const { track } = require('../../utils/tracking');

Page({
  data: {
    theme: getTheme(),
    themes: Object.values(THEMES),
    entryResult: null,
    todayDone: false,
    lastResult: null,
    atlas: [],
    hotResults: []
  },

  onLoad(options) {
    const scene = this.parseScene(options.scene);
    const theme = getTheme(options.theme || scene.t);
    const entryType = options.entry_result || scene.r;
    const entryResult = entryType && RESULTS[entryType] ? RESULTS[entryType] : null;
    this.refreshHome(theme, entryResult);
    wx.showShareMenu({
      withShareTicket: true,
      menus: ['shareAppMessage', 'shareTimeline']
    });
    track('page_view', {
      page_name: 'index',
      source_channel: options.source || 'direct',
      entry_result_type: entryResult ? entryResult.type : ''
    });
  },

  parseScene(scene) {
    if (!scene) return {};
    const pairs = decodeURIComponent(scene).split('&');
    return pairs.reduce((result, pair) => {
      const parts = pair.split('=');
      if (parts[0] && parts[1]) result[parts[0]] = parts[1];
      return result;
    }, {});
  },

  onShow() {
    this.refreshHome(this.data.theme, this.data.entryResult);
  },

  refreshHome(theme, entryResult) {
    const local = getLocalState();
    const lastResult = local.lastResultId && RESULTS[local.lastResultId] ? RESULTS[local.lastResultId] : null;
    const hotTypes = ['meeting_drained', 'low_battery', 'read_random_reply', 'countdown_runner'];
    const unlocked = {};
    (local.unlockedResultIds || []).forEach((type) => {
      unlocked[type] = true;
    });
    this.setData({
      theme,
      entryResult,
      weatherText: entryResult ? `朋友刚测出「${entryResult.name}」` : theme.weather,
      titleText: entryResult ? '测测你是不是同款' : theme.headline,
      todayDone: hasTestedToday(local),
      lastResult,
      hotResults: hotTypes.map((type) => {
        const result = RESULTS[type];
        return {
          type: result.type,
          name: result.name,
          oneLiner: result.oneLiner,
          accent: result.accent,
          rarityLabel: RARITY_LABEL[result.rarity]
        };
      }),
      atlas: RESULT_TYPES.map((type) => ({
        type,
        name: RESULTS[type].name,
        hint: RESULTS[type].unlockHint,
        unlocked: !!unlocked[type]
      }))
    });
  },

  selectTheme(event) {
    const theme = getTheme(event.currentTarget.dataset.id);
    this.setData({ theme });
    track('theme_select', { page_name: 'index', theme_id: theme.id });
  },

  startQuiz() {
    track('quiz_start', { page_name: 'index', theme_id: this.data.theme.id });
    wx.navigateTo({ url: `/pages/quiz/quiz?theme=${this.data.theme.id}` });
  },

  openLastResult() {
    if (!this.data.lastResult) return;
    wx.navigateTo({
      url: `/pages/result/result?type=${this.data.lastResult.type}&theme=${this.data.theme.id}`
    });
  },

  openAtlasItem(event) {
    const type = event.currentTarget.dataset.type;
    const item = this.data.atlas.find((entry) => entry.type === type);
    track('atlas_status_click', { page_name: 'index', result_type: type, unlocked: !!(item && item.unlocked) });
    if (item && item.unlocked) {
      wx.navigateTo({ url: `/pages/result/result?type=${type}&theme=${this.data.theme.id}` });
      return;
    }
    this.startQuiz();
  },

  openAbout() {
    wx.navigateTo({ url: '/pages/about/about' });
  },

  onShareAppMessage() {
    const fallback = {
      type: 'low_battery',
      shareTitle: '测测你今天还剩几格电',
      timelineTitle: '今日打工状态机',
      theme: this.data.theme
    };
    const payload = buildSharePayload(fallback, 'app_message');
    return {
      title: payload.title,
      path: payload.path
    };
  },

  onShareTimeline() {
    const fallback = {
      type: 'low_battery',
      shareTitle: '测测你今天还剩几格电',
      timelineTitle: '今日打工状态机',
      theme: this.data.theme
    };
    const payload = buildSharePayload(fallback, 'timeline');
    return {
      title: payload.title,
      query: payload.query
    };
  }
});

