const {
  answerMapToRefs,
  generateResult,
  getTheme,
  pickQuestionsForTheme
} = require('../../utils/result-engine');
const { saveResult } = require('../../utils/local-state');
const { track } = require('../../utils/tracking');

Page({
  data: {
    theme: getTheme(),
    questions: [],
    currentIndex: 0,
    currentQuestion: null,
    progress: 0,
    progressStage: '开机中',
    answers: {},
    feedback: '',
    locked: false
  },

  onLoad(options) {
    const theme = getTheme(options.theme);
    const questions = pickQuestionsForTheme(theme.id);
    this.setData({
      theme,
      questions,
      currentQuestion: questions[0],
      progress: 100 / questions.length,
      progressStage: this.getProgressStage(0)
    });
    track('page_view', { page_name: 'quiz', theme_id: theme.id });
  },

  selectAnswer(event) {
    if (this.data.locked) return;
    const answerId = event.currentTarget.dataset.id;
    const question = this.data.currentQuestion;
    const option = question.options.find((item) => item.id === answerId);
    const answers = Object.assign({}, this.data.answers);
    answers[question.id] = answerId;

    track('question_answer', {
      page_name: 'quiz',
      question_id: question.id,
      answer_id: answerId,
      theme_id: this.data.theme.id
    });
    track('answer_feedback_view', {
      page_name: 'quiz',
      question_id: question.id,
      theme_id: this.data.theme.id
    });

    this.setData({
      answers,
      feedback: option ? option.feedback : '状态信号已记录',
      locked: true
    });

    setTimeout(() => {
      if (this.data.currentIndex >= this.data.questions.length - 1) {
        this.finishQuiz(answers);
        return;
      }
      this.setQuestion(this.data.currentIndex + 1, answers);
    }, 780);
  },

  setQuestion(index, answers) {
    this.setData({
      currentIndex: index,
      currentQuestion: this.data.questions[index],
      progress: ((index + 1) / this.data.questions.length) * 100,
      progressStage: this.getProgressStage(index),
      answers: answers || this.data.answers,
      feedback: '',
      locked: false
    });
  },

  getProgressStage(index) {
    if (index < 3) return '开机中';
    if (index < 6) return '加载人格';
    return '生成工位档案';
  },

  goBackQuestion() {
    if (this.data.locked || this.data.currentIndex === 0) return;
    this.setQuestion(this.data.currentIndex - 1);
  },

  exitQuiz() {
    wx.navigateBack({ delta: 1 });
  },

  finishQuiz(answers) {
    const answerRefs = answerMapToRefs(answers);
    const result = generateResult(answerRefs, {
      themeId: this.data.theme.id,
      questions: this.data.questions
    });
    saveResult(result.type, this.data.theme.id);
    track('quiz_complete', {
      page_name: 'quiz',
      result_type: result.type,
      theme_id: this.data.theme.id
    });
    wx.redirectTo({
      url: `/pages/result/result?answers=${encodeURIComponent(answerRefs.join(','))}&theme=${this.data.theme.id}`
    });
  }
});

