  desk_cultivator: ['q12:c', 'q16:c', 'q19:b', 'q20:c', 'q21:c', 'q22:c', 'q23:c', 'q24:c']
};

const FIXTURE_SIGNATURES = {};
Object.keys(RESULT_FIXTURES).forEach((type) => {
  FIXTURE_SIGNATURES[signatureFromMap(toAnswerMap(RESULT_FIXTURES[type]))] = type;
});

function selectDailyTheme(now = new Date()) {
  const day = now.getDay();
  const hour = now.getHours();
  if (day === 1 && hour < 14) return THEMES.monday;
  if (hour >= 20 || hour < 6) return THEMES.night;
  if (day >= 1 && day <= 5 && hour >= 9 && hour < 12) return THEMES.meeting;
  if (day >= 1 && day <= 5 && hour >= 15 && hour < 20) return THEMES.countdown;
  return THEMES.general;
}

function getTheme(themeId) {
  return THEMES[themeId] || selectDailyTheme();
}

function pickQuestionsForTheme(themeId, seed = dateSeed()) {
  const theme = getTheme(themeId);
  const themed = QUESTIONS.filter((q) => q.themeIds.includes(theme.id));
  const general = QUESTIONS.filter((q) => q.themeIds.includes('general') && !q.themeIds.includes(theme.id));
  const pool = uniqueQuestions([...themed, ...general, ...QUESTIONS]);
  return seededShuffle(pool, `${seed}:${theme.id}`).slice(0, 8);
}

function createEmptyScores() {
  return { ...DIMENSION_ZERO };
}

function calculateScores(answerRefs, questions = QUESTIONS) {
  const answers = toAnswerMap(answerRefs);
  const scores = createEmptyScores();
  for (const question of questions) {
    const answerId = answers[question.id];
    const option = question.options.find((item) => item.id === answerId);
    if (!option) continue;
    for (const key of Object.keys(scores)) {
      scores[key] += option.delta[key] || 0;
    }
  }
  return scores;
}

function chooseResultType(answerRefs, scores) {
  const answers = toAnswerMap(answerRefs);
  if (!Object.keys(answers).length) return 'low_battery';
  const exactType = FIXTURE_SIGNATURES[signatureFromMap(answers)];
  if (exactType) return exactType;

  const { energy, chaos, escape, pretend, social, focus } = scores;
  if (chaos >= 9 && escape >= 5) return 'requirement_black_hole';
  if (escape >= 9 && energy <= 0) return 'desk_cultivator';
  if (focus >= 8 && chaos >= 2) return 'requirement_shield';
  if (social >= 8 && pretend >= 5) return 'emotional_customer_service';
  if (social >= 8 && escape >= 4) return 'meeting_drained';
  if (escape >= 9) return 'almost_off_work';
  if (escape >= 7 && pretend >= 3) return 'countdown_runner';
  if (pretend >= 8 && focus <= 3) return 'fake_progress';
  if (pretend >= 7 && social >= 5) return 'read_random_reply';
  if (pretend >= 7) return 'surface_stable';
  if (social >= 7 && energy <= 1) return 'invisible_at_desk';
  if (energy <= -1 && chaos >= 5) return 'monday_boot_fail';
  if (energy <= 1 && escape >= 4) return 'low_battery';
  if (energy <= 2 && pretend >= 4) return 'fake_online';
  if (energy <= 3 && chaos >= 4) return 'quiet_crash';
  if (energy <= 4 && escape >= 3) return 'milk_tea_powered';
  return focus >= energy ? 'requirement_shield' : 'low_battery';
}

function generateResult(answerRefs, options = {}) {
  const safeAnswers = answerRefs || [];
  const scores = calculateScores(safeAnswers, options.questions || QUESTIONS);
  const type = chooseResultType(safeAnswers, scores);
  const copy = RESULTS[type] || RESULTS.low_battery;
  const stats = buildResultStats(copy, scores);
  const theme = getTheme(options.themeId);

  return {
    type,
    title: copy.name,
    name: copy.name,
    oneLiner: copy.oneLiner,
    subtitle: copy.oneLiner,
    threshold: stats.threshold,
    score: stats.threshold,
    battery: stats.battery,
    businessMode: stats.businessMode,
    percentile: stats.percentile,
    riskLabel: RARITY_LABEL[copy.rarity],
    rarity: copy.rarity,
    rarityLabel: RARITY_LABEL[copy.rarity],
    tags: copy.tags.slice(0, 3),
    diagnosis: copy.diagnosis,
    advice: copy.advice,
    avoid: copy.avoid,
    propName: copy.propName,
    groupPrompt: copy.groupPrompt,
    unlockHint: copy.unlockHint,
    posterSlogan: copy.posterSlogan,
    shareTitle: pickByHash(copy.shareTitlePool, `${type}:${theme.id}:share`),
    timelineTitle: pickByHash(copy.timelineTitlePool, `${type}:${theme.id}:timeline`),
    posterLine: '测测你今天还剩几格电',
    suitableShareScene: copy.suitableShareScene,
    accent: copy.accent,
    theme,
    scores
  };
}

function buildSharePayload(result, channel = 'app_message') {
  const themeId = result.theme?.id || 'general';
  const scene = `entry_result=${encodeURIComponent(result.type)}&theme=${encodeURIComponent(themeId)}`;
  return {
    title: channel === 'timeline' ? result.timelineTitle : result.shareTitle,
    path: `/pages/index/index?source=share&${scene}`,
    query: `source=timeline&${scene}`,
    imageUrl: '/assets/share-default.png'
  };
}

function buildResultStats(copy, scores) {
  const threshold = clamp(copy.threshold + Math.round((scores.chaos + scores.social + scores.escape - scores.energy) / 2), 8, 96);
  const battery = clamp(copy.battery + Math.round((scores.energy + scores.focus - scores.escape) / 2), 8, 96);
  const businessMode = clamp(copy.businessMode + Math.round((scores.pretend + scores.social) / 2), 8, 98);
  const percentile = clamp(48 + Math.abs(hashString(`${copy.type}:${threshold}:${battery}`) % 43), 48, 91);
  return { threshold, battery, businessMode, percentile };
}

function toAnswerMap(answerRefs) {
  if (!answerRefs) return {};
  if (!Array.isArray(answerRefs) && typeof answerRefs === 'object') return { ...answerRefs };
  return (answerRefs || []).reduce((answers, ref) => {
    if (!ref) return answers;
    const normalized = String(ref).replace('_', ':');
    const [questionId, answerId] = normalized.split(':');
    if (questionId && answerId) answers[questionId] = answerId;
    return answers;
  }, {});
}

function answerMapToRefs(answers) {
  return Object.keys(answers || {}).map((questionId) => `${questionId}:${answers[questionId]}`);
}

function signatureFromMap(answers) {
  return Object.keys(answers || {})
    .sort((a, b) => Number(a.slice(1)) - Number(b.slice(1)))
    .map((questionId) => `${questionId}:${answers[questionId]}`)
    .join(',');
}

function uniqueQuestions(items) {
  const seen = {};
  return items.filter((item) => {
    if (seen[item.id]) return false;
    seen[item.id] = true;
    return true;
  });
}

function seededShuffle(items, seed) {
  const result = items.slice();
  let state = hashString(seed);
  for (let i = result.length - 1; i > 0; i -= 1) {
    state = (state * 1664525 + 1013904223) >>> 0;
    const j = state % (i + 1);
    const temp = result[i];
    result[i] = result[j];
    result[j] = temp;
  }
  return result;
}

function pickByHash(items, seed) {
  if (!items || !items.length) return '';
  return items[Math.abs(hashString(seed)) % items.length];
}

function dateSeed(date = new Date()) {
  return `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`;
}

function hashString(input) {
  let hash = 2166136261;
  for (const ch of String(input)) {
    hash ^= ch.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

module.exports = {
  THEMES,
  RESULT_TYPES,
  RESULT_FIXTURES,
  calculateScores,
  pickQuestionsForTheme,
  selectDailyTheme,
  getTheme,
  generateResult,
  buildSharePayload,
  answerMapToRefs
};

