const STORAGE_KEY = 'work_state_machine_v2';

function todayKey(date = new Date()) {
  return `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`;
}

function getLocalState() {
  try {
    return wx.getStorageSync(STORAGE_KEY) || { unlockedResultIds: [] };
  } catch (error) {
    return { unlockedResultIds: [] };
  }
}

function saveResult(resultType, themeId) {
  const current = getLocalState();
  const unlockedMap = {};
  (current.unlockedResultIds || []).forEach((type) => {
    unlockedMap[type] = true;
  });
  unlockedMap[resultType] = true;
  const next = {
    lastTestDate: todayKey(),
    lastResultId: resultType,
    unlockedResultIds: Object.keys(unlockedMap),
    lastThemeId: themeId || current.lastThemeId || 'general'
  };
  wx.setStorageSync(STORAGE_KEY, next);
  return next;
}

function hasTestedToday(state = getLocalState()) {
  return state.lastTestDate === todayKey() && !!state.lastResultId;
}

module.exports = {
  getLocalState,
  hasTestedToday,
  saveResult,
  todayKey
};

