export function selectDailyTheme(now = new Date()): ThemeDef {
  const day = now.getDay();
  const hour = now.getHours();
  if (day === 1 && hour < 14) return THEMES.monday;
  if (hour >= 20 || hour < 6) return THEMES.night;
  if (day >= 1 && day <= 5 && hour >= 9 && hour < 12) return THEMES.meeting;
  if (day >= 1 && day <= 5 && hour >= 15 && hour < 20) return THEMES.countdown;
  return THEMES.general;
}

export function getTheme(id?: string | null): ThemeDef {
  if (id && id in THEMES) return THEMES[id as ThemeId];
  return selectDailyTheme();
}

export function pickQuestionsForTheme(themeId: ThemeId, seed = getDateSeed()): Question[] {
  const themed = QUESTIONS.filter((q) => q.themeIds.includes(themeId));
  const general = QUESTIONS.filter(
    (q) => q.themeIds.includes("general") && !q.themeIds.includes(themeId),
  );
  const pool = uniqueQuestions([...themed, ...general, ...QUESTIONS]);
  return seededShuffle(pool, `${seed}:${themeId}`).slice(0, 8);
}

export function tally(answers: Answers, questions: Question[] = QUESTIONS): Dimensions {
  const dim: Dimensions = { ...DIMENSION_ZERO };
  for (const q of questions) {
    const ansId = answers[q.id];
    const opt = q.options.find((o) => o.id === ansId);
    if (!opt) continue;
    for (const k of Object.keys(opt.delta) as (keyof Dimensions)[]) {
      dim[k] += opt.delta[k] ?? 0;
    }
  }
  return dim;
}

export function computeResult(answers: Answers, questions: Question[] = QUESTIONS): ResultType {
  const d = tally(answers, questions);
  const { energy, chaos, escape, pretend, social, focus } = d;

  if (chaos >= 9 && escape >= 5) return "requirement_black_hole";
  if (escape >= 9 && energy <= 0) return "desk_cultivator";
  if (focus >= 8 && chaos >= 2) return "requirement_shield";
  if (social >= 8 && pretend >= 5) return "emotional_customer_service";
  if (social >= 8 && escape >= 4) return "meeting_drained";
  if (escape >= 9) return "almost_off_work";
  if (escape >= 7 && pretend >= 3) return "countdown_runner";
  if (pretend >= 8 && focus <= 3) return "fake_progress";
  if (pretend >= 7 && social >= 5) return "read_random_reply";
  if (pretend >= 7) return "surface_stable";
  if (social >= 7 && energy <= 1) return "invisible_at_desk";
  if (energy <= -1 && chaos >= 5) return "monday_boot_fail";
  if (energy <= 1 && escape >= 4) return "low_battery";
  if (energy <= 2 && pretend >= 4) return "fake_online";
  if (energy <= 3 && chaos >= 4) return "quiet_crash";
  if (energy <= 4 && escape >= 3) return "milk_tea_powered";
  return focus >= energy ? "requirement_shield" : "low_battery";
}

export const RESULT_FIXTURES: Record<ResultType, Answers> = Object.fromEntries(
  Object.entries(RESULT_FIXTURE_IDS).map(([type, encoded]) => [
    type,
    Object.fromEntries(encoded.split(",").map((pair) => pair.split(":"))),
  ]),
) as Record<ResultType, Answers>;

export function isResultType(s: string): s is ResultType {
  return s in RESULTS;
}

export function buildResultStats(type: ResultType, answers?: Answers, questions?: Question[]) {
  const result = RESULTS[type];
  const dims = answers ? tally(answers, questions) : null;
  const modifier = dims ? clamp((dims.focus + dims.pretend - dims.escape + 12) * 2, 0, 24) : 12;
  return {
    threshold: clamp(result.threshold + Math.round((result.threshold - 50) / 16), 8, 96),
    battery: clamp(result.battery + Math.round(modifier / 3) - 4, 8, 96),
    businessMode: clamp(result.businessMode + Math.round((dims?.pretend ?? 3) * 1.5), 8, 98),
    percentile: clamp(48 + Math.abs(hashString(`${type}:${modifier}`) % 43), 48, 91),
  };
}

function getDateSeed() {
  const d = new Date();
  return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;
}

function uniqueQuestions(items: Question[]) {
  const seen = new Set<string>();
  return items.filter((item) => {
    if (seen.has(item.id)) return false;
    seen.add(item.id);
    return true;
  });
}

function seededShuffle<T>(items: T[], seed: string) {
  const result = [...items];
  let state = hashString(seed);
  for (let i = result.length - 1; i > 0; i -= 1) {
    state = (state * 1664525 + 1013904223) >>> 0;
    const j = state % (i + 1);
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

function hashString(input: string) {
  let hash = 2166136261;
  for (const ch of input) {
    hash ^= ch.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

