exports.main = async (event) => {
  const wxContext = cloud.getWXContext();
  const events = Array.isArray(event.events) ? event.events : [];
  const now = new Date();

  if (!events.length) {
    return { ok: true, inserted: 0 };
  }

  const tasks = events.slice(0, 20).map((item) => {
    const record = {
      ...item,
      openid_hash: wxContext.OPENID ? Buffer.from(wxContext.OPENID).toString('base64') : '',
      created_at: item.created_at || now.toISOString(),
      server_created_at: now
    };
    return db.collection('events').add({ data: record });
  });

  await Promise.all(tasks);
  return { ok: true, inserted: tasks.length };
};

